(function(){
if(!document.getElementById('acp-pcfg-range-css')){var st=document.createElement('style');st.id='acp-pcfg-range-css';st.textContent='.pcfg-range{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:12px;padding:10px 12px;background:var(--bg-secondary);border:1px solid var(--border);border-radius:8px}.pcfg-range-lbl{font-size:11px;text-transform:uppercase;letter-spacing:.5px;color:var(--text-secondary,#a0937e);font-weight:600}.pcfg-range input[type=date]{padding:5px 8px;background:var(--bg-card);border:1px solid var(--border);border-radius:5px;color:var(--text-primary);font-size:12px;font-family:inherit;color-scheme:dark}.pcfg-range-sep{color:var(--text-secondary,#a0937e)}.pcfg-rst{margin-left:auto;padding:5px 10px;background:var(--bg-card);border:1px solid var(--border);border-radius:5px;color:var(--text-secondary,#a0937e);font-size:11px;cursor:pointer;font-family:inherit}.pcfg-rst:hover{color:var(--accent-orange);border-color:var(--accent-orange)}';document.head.appendChild(st);}
var BASE='https://xetg-lio4-hwsh.p7.xano.io/api:1LlCmuZl';
function authH(){return {Authorization:'Bearer '+(localStorage.getItem('xano_token')||'')};}
window.enrichPerfData=function(){
var el=document.getElementById('perf-data');if(!el)return;
if(!window._perfCfg)window._perfCfg=[{m:'perf',n:1,u:'y'},{m:'vol',n:5,u:'y'},{m:'mdd',n:5,u:'y'},{m:'cagr',n:10,u:'y'},{m:'beta',n:5,u:'y',b:'SPY'}];
var ML={perf:'Performance',cagr:'CAGR',vol:'Volatilité ann.',mdd:'Max Drawdown',beta:'Beta'},UL={y:'ans',m:'mois',d:'jours'},BL={SPY:'S&P 500',QQQ:'Nasdaq 100',DIA:'Dow Jones',VGK:'Europe'};
function sd(n,u){var d=new Date();n=Math.max(1,n||1);u==='y'?d.setFullYear(d.getFullYear()-n):u==='m'?d.setMonth(d.getMonth()-n):d.setDate(d.getDate()-n);return d.toISOString().slice(0,10);}
function cmp(m,n,u){var o=window.oD;if(!o||o.length<10)return null;var st=sd(n,u),w=[];for(var i=0;i<o.length;i++)if(o[i].date>=st)w.push(o[i]);if(w.length<2)w=o.slice();var L=o[o.length-1].close;if(!(L>0))return null;
if(m==='perf'){var s=w[0].close;return s>0?(L/s-1)*100:null;}
if(m==='cagr'){var s2=w[0].close,y=(new Date(o[o.length-1].date)-new Date(w[0].date))/(365.25*864e5);return s2>0&&y>0.05?(Math.pow(L/s2,1/y)-1)*100:null;}
if(m==='vol'){var r=[];for(var j=1;j<w.length;j++)if(w[j-1].close>0)r.push(Math.log(w[j].close/w[j-1].close));if(r.length<20)return null;var mu=r.reduce(function(p,q){return p+q},0)/r.length,v=0;for(var k=0;k<r.length;k++)v+=(r[k]-mu)*(r[k]-mu);return Math.sqrt(v/r.length)*Math.sqrt(252)*100;}
if(m==='mdd'){var pk=0,dd=0;for(var p=0;p<w.length;p++){var c=w[p].close;if(c>pk)pk=c;var x=pk>0?(pk-c)/pk:0;if(x>dd)dd=x;}return -dd*100;}
return null;}
function _win(from,to){var o=window.oD||[];var w=[];for(var i=0;i<o.length;i++){var d=o[i].date;if((!from||d>=from)&&(!to||d<=to))w.push(o[i]);}return w;}
function cmpR(m,from,to){var o=window.oD;if(!o||o.length<2)return null;var w=_win(from,to);if(w.length<2)return null;var L=w[w.length-1].close;if(!(L>0))return null;
if(m==='perf'){var s0=w[0].close;return s0>0?(L/s0-1)*100:null;}
if(m==='cagr'){var s2=w[0].close,y=(new Date(w[w.length-1].date)-new Date(w[0].date))/(365.25*864e5);return s2>0&&y>0.05?(Math.pow(L/s2,1/y)-1)*100:null;}
if(m==='vol'){var r=[];for(var j=1;j<w.length;j++)if(w[j-1].close>0)r.push(Math.log(w[j].close/w[j-1].close));if(r.length<20)return null;var mu=r.reduce(function(p,q){return p+q},0)/r.length,v=0;for(var k=0;k<r.length;k++)v+=(r[k]-mu)*(r[k]-mu);return Math.sqrt(v/r.length)*Math.sqrt(252)*100;}
if(m==='mdd'){var pk=0,dd=0;for(var p=0;p<w.length;p++){var c=w[p].close;if(c>pk)pk=c;var x=pk>0?(pk-c)/pk:0;if(x>dd)dd=x;}return -dd*100;}
return null;}
function bcalc(o,bo,st){var bm={};for(var i=0;i<bo.length;i++)bm[bo[i].date]=bo[i].close;var P=[];for(i=0;i<o.length;i++){var d=o[i].date;if(d<st)continue;var b=bm[d];if(!(b>0))continue;var s=o[i].close;if(!(s>0))continue;P.push([s,b]);}if(P.length<20)return null;var X=[],Y=[];for(i=1;i<P.length;i++){X.push(Math.log(P[i][0]/P[i-1][0]));Y.push(Math.log(P[i][1]/P[i-1][1]));}var n=X.length,mx=0,my=0;for(i=0;i<n;i++){mx+=X[i];my+=Y[i];}mx/=n;my/=n;var cv=0,vy=0;for(i=0;i<n;i++){cv+=(X[i]-mx)*(Y[i]-my);vy+=(Y[i]-my)*(Y[i]-my);}return vy>0?cv/vy:null;}
function lbench(tk,cb){window._bc=window._bc||{};if(window._bc[tk]!==undefined){cb(window._bc[tk]);return;}fetch(BASE+'/fmp/historical?ticker='+encodeURIComponent(tk),{headers:authH()}).then(function(r){return r.json();}).then(function(d){var a=(d&&d.historical&&d.historical.length)?d.historical.slice().reverse():null;window._bc[tk]=a;cb(a);}).catch(function(){window._bc[tk]=null;cb(null);});}
function fmt(m,v){if(v===null||v===undefined||isNaN(v))return{t:'—',c:'#6b5f50'};if(m==='vol')return{t:v.toFixed(1)+'%',c:v>30?'#e8524a':v>20?'#e8913a':'#6dd8a8'};if(m==='mdd')return{t:v.toFixed(1)+'%',c:'#e8524a'};if(m==='beta')return{t:v.toFixed(2),c:v>1.2?'#e8524a':v<0.8?'#3ec98c':'#e8d5b0'};return{t:(v>=0?'+':'')+v.toFixed(1)+'%',c:v>=0?'#3ec98c':'#e8524a'};}
function opts(mp,sl){return Object.keys(mp).map(function(k){return '<option value="'+k+'"'+(k===sl?' selected':'')+'>'+mp[k]+'</option>';}).join('');}
function setV(bx,c){var bs=bx.querySelector('.pcfg-b');if(bs)bs.style.display=c.m==='beta'?'':'none';var v=bx.querySelector('.pcfg-v');if(c.m!=='beta'){var R=window._perfRange;var val=(R&&R.from&&R.to)?cmpR(c.m,R.from,R.to):cmp(c.m,c.n,c.u);var f=fmt(c.m,val);v.textContent=f.t;v.style.color=f.c;bx.style.borderLeftColor=f.c;return;}var o=window.oD;if(!o||o.length<20){v.textContent='—';v.style.color='#6b5f50';return;}v.textContent='...';var R=window._perfRange;var st=(R&&R.from&&R.to)?R.from:sd(c.n,c.u);lbench(c.b||'SPY',function(bo){if(bx.querySelector('.pcfg-m').value!=='beta')return;var f=fmt('beta',bo?bcalc(o,bo,st):null);v.textContent=f.t;v.style.color=f.c;bx.style.borderLeftColor=f.c;});}
function box(c,i){return '<div class="pcfg" data-i="'+i+'"><div class="pcfg-ctrls"><select class="pcfg-m">'+opts(ML,c.m)+'</select><select class="pcfg-b" style="display:'+(c.m==='beta'?'':'none')+'">'+opts(BL,c.b||'SPY')+'</select><input class="pcfg-n" type="number" min="1" value="'+c.n+'"><select class="pcfg-u">'+opts(UL,c.u)+'</select></div><div class="pcfg-v">...</div></div>';}
function render(){var o=window.oD||[];var dmin=o.length?o[0].date:'';var dmax=o.length?o[o.length-1].date:'';var R=window._perfRange||{};var bar='<div class="pcfg-range">'+'<span class="pcfg-range-lbl">Période personnalisée</span>'+'<input type="date" class="pcfg-d1" min="'+dmin+'" max="'+dmax+'" value="'+(R.from||'')+'">'+'<span class="pcfg-range-sep">→</span>'+'<input type="date" class="pcfg-d2" min="'+dmin+'" max="'+dmax+'" value="'+(R.to||'')+'">'+'<button class="pcfg-rst" type="button">Réinitialiser</button>'+'</div>';var h=bar+'<div class="pcfg-grid">';window._perfCfg.forEach(function(c,i){h+=box(c,i);});h+='</div>';el.innerHTML=h;el.querySelectorAll('.pcfg').forEach(function(bx){var i=parseInt(bx.dataset.i);function up(){var c=window._perfCfg[i];if(!c)return;c.m=bx.querySelector('.pcfg-m').value;c.b=bx.querySelector('.pcfg-b').value;c.n=Math.max(1,parseInt(bx.querySelector('.pcfg-n').value)||1);c.u=bx.querySelector('.pcfg-u').value;setV(bx,c);}bx.querySelector('.pcfg-m').addEventListener('change',up);bx.querySelector('.pcfg-b').addEventListener('change',up);bx.querySelector('.pcfg-u').addEventListener('change',up);bx.querySelector('.pcfg-n').addEventListener('input',up);setV(bx,window._perfCfg[i]);});var d1=el.querySelector('.pcfg-d1'),d2=el.querySelector('.pcfg-d2'),rst=el.querySelector('.pcfg-rst');function applyRange(){var a=d1&&d1.value,b=d2&&d2.value;if(a&&b&&a<=b){window._perfRange={from:a,to:b};}else{window._perfRange=null;}el.querySelectorAll('.pcfg').forEach(function(bx){var i=parseInt(bx.dataset.i);setV(bx,window._perfCfg[i]);});}if(d1)d1.addEventListener('change',applyRange);if(d2)d2.addEventListener('change',applyRange);if(rst)rst.addEventListener('click',function(){window._perfRange=null;if(d1)d1.value='';if(d2)d2.value='';el.querySelectorAll('.pcfg').forEach(function(bx){var i=parseInt(bx.dataset.i);setV(bx,window._perfCfg[i]);});});}
render();};
})();